package main

import (
	"log"

	"github.com/3io-w/strawbery-mcp/internal/tool/count"
	"github.com/mark3labs/mcp-go/server"
)

func main() {
	s := server.NewMCPServer(
		"Strawbery-MCP",
		"1.0.0",
		server.WithToolCapabilities(true),
	)

	s.AddTool(count.CountTool, count.HandleCount)

	sseServer := server.NewSSEServer(s, server.WithSSEEndpoint("/sse"))

	log.Println("strawbery-mcp running")

	if err := sseServer.Start(":3001"); err != nil {
		log.Fatal(err)
	}
}
